/* Release Desk interaction prototype. All records and actions are local demo data. */
const root = document.getElementById('app');
const icons = {
  grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
  store:'<path d="M3 10h18l-1-5H4l-1 5Z"/><path d="M5 10v10h14V10M9 20v-6h6v6"/>',
  plus:'<path d="M12 5v14M5 12h14"/>',
  arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',
  left:'<path d="m15 18-6-6 6-6"/>',
  close:'<path d="M5 5l14 14M19 5 5 19"/>',
  folder:'<path d="M3 7V5a2 2 0 0 1 2-2h5l2 3h7a2 2 0 0 1 2 2v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V7Z"/>',
  repo:'<path d="M7 3a2 2 0 1 0 0 4 2 2 0 0 0 0-4Zm0 4v9a4 4 0 0 0 4 4h2M17 17a2 2 0 1 0 0 4 2 2 0 0 0 0-4Zm0-14v10a4 4 0 0 1-4 4"/>',
  spark:'<path d="m12 2 2.1 7.9L22 12l-7.9 2.1L12 22l-2.1-7.9L2 12l7.9-2.1L12 2Z"/>',
  download:'<path d="M12 3v12m-4-4 4 4 4-4M4 17v4h16v-4"/>',
  settings:'<path d="M10 3h4l.7 2.1 2 .8 2-.9 2.8 2.8-.9 2 .8 2L23 12v4l-2.1.7-.8 2 .9 2-2.8 2.8-2-.9-2 .8L14 25h-4l-.7-2.1-2-.8-2 .9-2.8-2.8.9-2-.8-2L.5 16v-4l2.1-.7.8-2-.9-2L5.3 4.5l2 .9 2-.8L10 3Z" transform="translate(2 2) scale(.8)"/><circle cx="12" cy="12" r="3"/>',
  monitor:'<rect x="3" y="4" width="18" height="14" rx="2"/><path d="M8 22h8m-4-4v4"/>',
  shield:'<path d="M12 22s8-4 8-11V5l-8-3-8 3v6c0 7 8 11 8 11Z"/><path d="m9 12 2 2 4-4"/>',
  check:'<path d="m4 12 5 5L20 6"/>',
  list:'<path d="M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01"/>',
  layers:'<path d="m12 3 9 5-9 5-9-5 9-5Zm-9 9 9 5 9-5M3 16l9 5 9-5"/>'
};
const svg=(name,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.spark}</svg>`;
const escapeHtml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nice=s=>String(s||'').replace(/(^|[-_\s])\w/g,m=>m.toUpperCase());
const bytes=n=>n>=1e9?(n/1e9).toFixed(1)+' GB':n>=1e6?Math.round(n/1e6)+' MB':Math.round(n/1e3)+' KB';
const providers=[
  {id:'github',name:'GitHub',sub:'Cloud or Enterprise',mark:'GH'},
  {id:'gitlab',name:'GitLab',sub:'Cloud or self hosted',mark:'GL'},
  {id:'bitbucket',name:'Bitbucket',sub:'Cloud or Data Center',mark:'BB'},
  {id:'azure',name:'Azure DevOps',sub:'Azure Repos',mark:'AZ'},
  {id:'gitea',name:'Gitea',sub:'Self hosted',mark:'GT'},
  {id:'forgejo',name:'Forgejo',sub:'Self hosted',mark:'FJ'},
  {id:'codeberg',name:'Codeberg',sub:'Hosted Forgejo',mark:'CB'},
  {id:'codecommit',name:'AWS CodeCommit',sub:'AWS repositories',mark:'AWS'},
  {id:'custom',name:'Custom Git',sub:'Any HTTPS Git server',mark:'+'}
];
const repoCatalog={
  prism:{id:'prism',name:'Prism Studio',owner:'northstar-labs',type:'Creative tools',description:'A desktop workspace for visual storytelling, moodboards, and real-time previews.',icon:'prism.svg',url:'https://example.com/northstar-labs/prism-studio',private:false,branch:'main',releases:[{tag:'v2.8.0',date:'Oct 24, 2026',notes:'New canvas presets, faster preview rendering, and refined export controls.',assets:[{name:'Prism-2.8.0-universal.dmg',platform:'macOS',size:188e6,type:'DMG'},{name:'Prism-2.8.0-setup.exe',platform:'Windows',size:142e6,type:'EXE installer'},{name:'Prism-2.8.0.AppImage',platform:'Linux',size:156e6,type:'AppImage'}]},{tag:'v2.7.2',date:'Sep 16, 2026',notes:'Stability improvements and color profile fixes.',assets:[]}]},
  quill:{id:'quill',name:'Quill Notes',owner:'northstar-labs',type:'Productivity',description:'A focused writing app with linked notes and a clean distraction-free editor.',icon:'quill.svg',url:'https://example.com/northstar-labs/quill-notes',private:false,branch:'main',releases:[{tag:'v1.6.3',date:'Oct 18, 2026',notes:'Improved search and offline notebooks.',assets:[{name:'Quill-1.6.3.pkg',platform:'macOS',size:56e6,type:'PKG installer'},{name:'Quill-1.6.3.msi',platform:'Windows',size:63e6,type:'MSI'},{name:'Quill-1.6.3.deb',platform:'Linux',size:51e6,type:'DEB'}]}]},
  atlas:{id:'atlas',name:'Atlas Maps',owner:'northstar-labs',type:'Developer tools',description:'Explore geographic data layers and build map-driven prototypes.',icon:'atlas.svg',url:'https://example.com/northstar-labs/atlas-maps',private:true,branch:'main',releases:[{tag:'v0.9.5',date:'Oct 12, 2026',notes:'Better layer controls and export support.',assets:[{name:'Atlas-0.9.5-macos.zip',platform:'macOS',size:92e6,type:'ZIP app'},{name:'Atlas-0.9.5-setup.exe',platform:'Windows',size:103e6,type:'EXE installer'}]}]},
  orbit:{id:'orbit',name:'Orbit Tasks',owner:'orbit-team',type:'Productivity',description:'A lightweight task board for small teams working across time zones.',icon:'orbit.svg',url:'https://example.com/orbit-team/orbit-tasks',private:false,branch:'main',releases:[{tag:'v3.1.0',date:'Oct 21, 2026',notes:'Timeline view and smart recurring tasks.',assets:[{name:'Orbit-3.1.0.dmg',platform:'macOS',size:79e6,type:'DMG'},{name:'Orbit-3.1.0.msi',platform:'Windows',size:84e6,type:'MSI'},{name:'Orbit-3.1.0.flatpak',platform:'Linux',size:91e6,type:'Flatpak'}]}]},
  relay:{id:'relay',name:'Relay Client',owner:'community',type:'Developer tools',description:'A clear, fast client for inspecting API requests and live streams.',icon:'relay.svg',url:'https://example.com/community/relay-client',private:false,branch:'stable',releases:[{tag:'v1.2.1',date:'Oct 15, 2026',notes:'New request history and keyboard shortcuts.',assets:[{name:'Relay-1.2.1.dmg',platform:'macOS',size:72e6,type:'DMG'},{name:'Relay-1.2.1.exe',platform:'Windows',size:75e6,type:'EXE'},{name:'Relay-1.2.1.AppImage',platform:'Linux',size:80e6,type:'AppImage'}]}]}
};
const seedProjects=[
 {id:'northstar',name:'Northstar Suite',folder:'~/Projects/Northstar',provider:'github',account:'northstar-labs',disk:'grouped',sources:['northstar-labs','helen-designs'],repos:['prism','quill','atlas'],demo:true},
 {id:'orbit-team',name:'Orbit Team Tools',folder:'~/Work/Orbit',provider:'gitlab',account:'orbit-team',disk:'flat',sources:['orbit-team'],repos:['orbit'],demo:true},
 {id:'community',name:'Community Builds',folder:'~/Code/Community',provider:'forgejo',account:'community',disk:'grouped',sources:['community'],repos:['relay'],demo:true}
];
const storageKey='release-desk-design-v1';
let saved;try{saved=JSON.parse(localStorage.getItem(storageKey)||'null')}catch{}
let state={projects:saved?.projects||structuredClone(seedProjects),installs:saved?.installs||{orbit:'v3.0.0',quill:'v1.6.3'},view:'hub',projectId:null,tab:'overview',repoId:'prism',listMode:'grouped',platform:'macOS',storePlatform:'All',search:'',modal:null,wizard:{step:0,name:'',folder:'',provider:'github',host:'',account:'',disk:'grouped'},sourceDraft:'',toast:''};
const persist=()=>localStorage.setItem(storageKey,JSON.stringify({projects:state.projects,installs:state.installs}));
const project=()=>state.projects.find(p=>p.id===state.projectId);
const provider=p=>providers.find(x=>x.id===p)||providers[8];
const providerIcon=p=>p.id==='custom'?'+':`<img src="assets/${p.id==='codecommit'?'amazonaws':p.id}.svg" alt="" aria-hidden="true">`;
const repo=r=>repoCatalog[r]||{id:r,name:nice(r),owner:project()?.account||'demo',type:'Repository',description:'Sample repository for exploring the workspace flow.',icon:null,url:'https://example.com',private:false,branch:'main',releases:[]};
const icon=r=>r.icon?`<img class="app-icon" src="assets/${escapeHtml(r.icon)}" alt="">`:`<span class="app-icon icon-fallback">${escapeHtml(r.name?.charAt(0)||'?')}</span>`;
const projectRepos=p=>(p?.repos||[]).map(repo);
const installAction=r=>!state.installs[r.id]?'Install':state.installs[r.id]!==r.releases[0]?.tag?'Update':'Open';
const statusPill=p=>p.account?'<span class="chip green">Account selected</span>':'<span class="chip orange">Connect account</span>';
const toast=t=>{state.toast=t;render();clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>{state.toast='';render()},4000)};
const sidebar=()=>`<aside class="sidebar"><div class="brand"><span class="brand-mark">${svg('layers',19)}</span>Release Desk</div><div class="nav-label">WORKSPACE</div><nav aria-label="Main navigation"><button class="nav-item ${state.view==='hub'||state.view==='project'?'active':''}" data-action="hub">${svg('grid')}<span>Projects</span><span class="nav-count">${state.projects.length}</span></button><button class="nav-item ${state.view==='store'?'active':''}" data-action="store">${svg('store')}<span>App Store</span></button></nav><div class="sidebar-bottom"><strong>Design preview</strong>Explore the layout and flow. All records and actions are simulated in this browser.</div></aside>`;
const topbar=()=>`<header class="topbar"><div class="crumb"><span>Workspace</span><span>›</span><strong>${state.view==='project'?escapeHtml(project()?.name||'Project'):state.view==='store'?'App Store':'All projects'}</strong></div><div class="top-actions"><span class="prototype-pill"><i></i> INTERACTIVE PROTOTYPE</span><div class="avatar">RD</div></div></header>`;
function render(){root.innerHTML=`<div class="app-shell">${sidebar()}<main class="main">${topbar()}<div class="content">${state.view==='hub'?renderHub():state.view==='store'?renderStore():renderProject()}</div></main></div>${state.modal?renderModal():''}${state.toast?`<div class="toast" role="status">${escapeHtml(state.toast)} <button data-action="dismiss-toast" aria-label="Dismiss">×</button></div>`:''}`;}
function renderHub(){const counts={repos:state.projects.reduce((n,p)=>n+p.repos.length,0),sources:state.projects.reduce((n,p)=>n+p.sources.length,0),releases:state.projects.reduce((n,p)=>n+projectRepos(p).filter(r=>r.releases.length).length,0)};return `<div class="page-head"><div><div class="eyebrow">YOUR WORKSPACE</div><h1>Projects, all in one place.</h1><p>Each project has its own folder, Git provider, account, sources, and repository collection. Open a project to work inside it.</p></div><div class="head-actions"><button class="btn primary" data-action="new-project">${svg('plus')} New project</button></div></div><div class="hero"><div><div class="eyebrow">START HERE</div><h2>Build a workspace around a folder.</h2><p>Create a project, connect a provider account, add people or organizations, then choose the repositories you want to manage.</p><button class="btn small" style="margin-top:16px" data-action="new-project">Explore project setup ${svg('arrow',14)}</button></div><div class="hero-symbol">${svg('folder',48)}</div></div><div class="stat-grid"><div class="stat"><div class="num">${state.projects.length}</div><div class="label">Projects</div></div><div class="stat"><div class="num">${counts.sources}</div><div class="label">Source profiles</div></div><div class="stat"><div class="num">${counts.repos}</div><div class="label">Selected repositories</div></div><div class="stat"><div class="num">${counts.releases}</div><div class="label">Apps with releases</div></div></div><div class="section-head"><h2>All projects</h2><span class="muted">Folder and provider are unique to each project</span></div><div class="project-grid">${state.projects.map(renderProjectCard).join('')}</div>`}
function renderProjectCard(p){const pv=provider(p.provider);return `<article class="project-card clickable-card" role="button" tabindex="0" data-action="open-project" data-id="${escapeHtml(p.id)}" aria-label="Open ${escapeHtml(p.name)} project"><div class="project-top"><div class="provider-logo ${pv.id}">${providerIcon(pv)}</div><div><div class="project-name">${escapeHtml(p.name)}</div><div class="project-sub">${escapeHtml(pv.name)} · ${escapeHtml(p.account||'Account not selected')}</div></div></div><div class="card-path" title="${escapeHtml(p.folder)}">${escapeHtml(p.folder)}</div><div class="project-meta"><span class="chip blue">${p.sources.length} ${p.sources.length===1?'source':'sources'}</span><span class="chip">${p.repos.length} repositories</span><span class="chip">${p.disk==='grouped'?'Owner / repository':'Flat on disk'}</span></div><div class="project-footer"><span>${p.demo?'Sample project':'Created in this preview'}</span><button class="link-button" data-action="open-project" data-id="${escapeHtml(p.id)}">Open project →</button></div></article>`}
function renderProject(){const p=project();if(!p){state.view='hub';return renderHub()}const pv=provider(p.provider);const tabs=[['overview','Overview'],['sources','Sources'],['repositories','Repositories'],['releases','Releases'],['settings','Settings']];return `<div class="page-head"><div class="workspace-header"><span class="provider-logo ${pv.id}">${escapeHtml(pv.mark)}</span><div><div class="eyebrow">PROJECT WORKSPACE</div><h1 style="margin:3px 0 5px">${escapeHtml(p.name)}</h1><p>${escapeHtml(pv.name)} · ${escapeHtml(p.account||'Account not selected')} · ${escapeHtml(p.folder)}</p></div></div><div class="head-actions"><button class="btn" data-action="hub">${svg('left')} All projects</button></div></div><nav class="tabs" aria-label="Project sections">${tabs.map(([id,label])=>`<button class="tab ${state.tab===id?'active':''}" data-action="project-tab" data-tab="${id}">${label}${id==='repositories'?` <span style="color:#9aa5b4">${p.repos.length}</span>`:''}</button>`).join('')}</nav>${state.tab==='overview'?renderOverview(p):state.tab==='sources'?renderSources(p):state.tab==='repositories'?renderRepositories(p):state.tab==='releases'?renderReleases(p):renderProjectSettings(p)}`}
function renderOverview(p){const rs=projectRepos(p);return `<div class="stat-grid"><div class="stat"><div class="num">${p.sources.length}</div><div class="label">Sources</div></div><div class="stat"><div class="num">${p.repos.length}</div><div class="label">Repositories</div></div><div class="stat"><div class="num">${rs.filter(r=>r.releases.length).length}</div><div class="label">With releases</div></div><div class="stat"><div class="num">${Object.keys(state.installs).filter(id=>p.repos.includes(id)&&state.installs[id]).length}</div><div class="label">Installed in preview</div></div></div><div class="overview-layout"><section class="panel"><h3>What to do next</h3><div class="activity-item"><span class="activity-dot"></span><div><strong>Review sources and repositories</strong><span>Add a user or organization, then select which repositories belong in this project.</span></div></div><div class="activity-item"><span class="activity-dot" style="background:#11a57b"></span><div><strong>Choose release assets</strong><span>Compare available macOS, Windows, and Linux builds in Releases.</span></div></div><div class="activity-item"><span class="activity-dot" style="background:#f2a64b"></span><div><strong>Find apps in the shared store</strong><span>Installable apps from every project appear together in App Store.</span></div></div><button class="btn small" style="margin-top:16px" data-action="project-tab" data-tab="sources">Open sources ${svg('arrow',14)}</button></section><section class="panel"><h3>Project setup</h3><div class="info-list"><div class="info-row"><span>Provider</span><strong>${escapeHtml(provider(p.provider).name)}</strong></div><div class="info-row"><span>Account</span><strong>${escapeHtml(p.account||'Choose an account')}</strong></div><div class="info-row"><span>Folder</span><strong>${escapeHtml(p.folder)}</strong></div><div class="info-row"><span>Disk layout</span><strong>${p.disk==='grouped'?'Grouped by owner':'Flat'}</strong></div><div class="info-row"><span>Connection</span><strong style="color:var(--warn)">Preview only</strong></div></div></section></div>`}
function renderSources(p){return `<div class="toolbar"><div><div class="eyebrow">DISCOVERY</div><h2 style="font:800 19px var(--display);margin:5px 0">People and organizations</h2><p class="muted" style="font-size:12px;margin:0">Add a handle or profile link from ${escapeHtml(provider(p.provider).name)}. Review repositories before adding them.</p></div><button class="btn primary" data-action="add-source">${svg('plus')} Add source</button></div>${p.sources.length?`<div class="source-grid">${p.sources.map(s=>`<article class="card source-card"><div class="source-head"><div class="source-avatar">${escapeHtml(s.slice(0,1).toUpperCase())}</div><div><h3>${escapeHtml(s)}</h3><span class="muted" style="font-size:10px">${escapeHtml(provider(p.provider).name)} profile</span></div></div><p>Repository source in this project. Select a profile to review its tracked repositories.</p><span class="chip blue">${p.repos.filter(id=>repo(id).owner===s).length} selected repositories</span><br><button class="btn small" data-action="add-source">Add another source ${svg('arrow',12)}</button></article>`).join('')}</div>`:emptyState('No sources yet','Add a provider user or organization to find repositories.','add-source','Add a source')}`}
function renderRepositories(p){const rs=projectRepos(p).filter(r=>!state.search||`${r.name} ${r.description}`.toLowerCase().includes(state.search.toLowerCase()));const selected=rs.find(r=>r.id===state.repoId)||rs[0];const grouped=state.listMode==='grouped';return `<div class="toolbar"><div class="toolbar-left"><input class="search" id="repo-search" type="search" value="${escapeHtml(state.search)}" placeholder="Search repositories"><span class="muted" style="font-size:11px">${rs.length} repositories</span></div><div class="toolbar-right"><span class="muted" style="font-size:11px">List view</span><span class="segmented"><button data-action="list-mode" data-mode="grouped" class="${grouped?'active':''}">${svg('layers',13)} Grouped</button><button data-action="list-mode" data-mode="flat" class="${!grouped?'active':''}">${svg('list',13)} Flat</button></span></div></div>${p.repos.length?`<div class="repo-shell"><div class="repo-list">${rs.map((r,i)=>`${grouped&&(i===0||r.owner!==rs[i-1].owner)?`<div class="nav-label" style="padding:12px 17px 7px;background:#f8f9fc">${escapeHtml(r.owner)}</div>`:''}<button class="repo-row ${selected?.id===r.id?'active':''}" data-action="select-repo" data-id="${escapeHtml(r.id)}"><div class="repo-row-top">${icon(r)}<span class="repo-row-name">${escapeHtml(r.name)}</span>${r.private?'<span class="chip">Private</span>':''}</div><div class="repo-row-desc">${escapeHtml(r.description)}</div><div class="repo-row-meta"><span class="chip blue">${escapeHtml(r.releases[0]?.tag||'No release')}</span><span class="chip">${escapeHtml(r.branch)}</span></div></button>`).join('')||'<div class="empty-state">Nothing matches your search.</div>'}</div><div class="repo-detail">${selected?renderRepoDetail(selected):'<div class="empty-state">Select a repository.</div>'}</div></div>`:emptyState('No repositories selected','Add a source and choose which repositories to clone and manage.','add-source','Add a source')}`}
function renderRepoDetail(r){return `<div class="repo-detail-head">${icon(r)}<div><div class="eyebrow">${escapeHtml(r.owner)}</div><h2>${escapeHtml(r.name)}</h2></div></div><p>${escapeHtml(r.description)}</p><div class="detail-grid"><div class="detail-stat"><span>Visibility</span><strong>${r.private?'Private':'Public'}</strong></div><div class="detail-stat"><span>Default branch</span><strong>${escapeHtml(r.branch)}</strong></div><div class="detail-stat"><span>Latest release</span><strong>${escapeHtml(r.releases[0]?.tag||'None')}</strong></div></div><div class="section-head"><h2>Latest releases</h2><button class="link-button" data-action="project-tab" data-tab="releases">See release shelf →</button></div>${r.releases.length?r.releases.map(rel=>`<div class="release-item"><div class="release-item-head"><strong class="release-tag">${escapeHtml(rel.tag)}</strong><span class="release-date">${escapeHtml(rel.date)}</span></div><p style="margin:8px 0">${escapeHtml(rel.notes)}</p><div class="asset-line">${svg('download',14)} ${rel.assets.length} release assets across ${[...new Set(rel.assets.map(a=>a.platform))].join(', ')}</div></div>`).join(''):'<p>No published releases in this preview.</p>'}`}
function renderReleases(p){const rs=projectRepos(p).filter(r=>r.releases.length);const platforms=['macOS','Windows','Linux','All'];return `<div class="toolbar"><div><div class="eyebrow">RELEASES</div><h2 style="font:800 19px var(--display);margin:5px 0">Release shelf</h2><p class="muted" style="font-size:12px;margin:0">Latest upstream release, selected build, and previous build shown separately.</p></div><span class="segmented">${platforms.map(pl=>`<button data-action="platform" data-platform="${pl}" class="${state.platform===pl?'active':''}">${pl}</button>`).join('')}</span></div>${rs.length?rs.map(r=>{const rel=r.releases[0],assets=rel.assets.filter(a=>state.platform==='All'||a.platform===state.platform),current=assets[0];return `<article class="shelf-row"><div class="shelf-head">${icon(r)}<div><h3>${escapeHtml(r.name)}</h3><span class="muted" style="font-size:11px">${escapeHtml(r.owner)} · published ${escapeHtml(rel.date)}</span></div><span class="chip ${assets.length?'blue':'orange'}">${assets.length?`${assets.length} ${state.platform==='All'?'assets':state.platform+' builds'}`:'No build for '+state.platform}</span><span class="spacer"></span><button class="btn small" data-action="show-release" data-id="${escapeHtml(r.id)}">Release details ${svg('arrow',13)}</button></div><div class="shelf-slots"><div class="slot upstream"><b>Newest upstream</b><strong>${escapeHtml(rel.tag)}</strong><small>${escapeHtml(current?.name||'No matching asset')}</small></div><div class="slot local"><b>Selected asset</b><strong>${current?escapeHtml(current.type):'Choose a platform'}</strong><small>${current?`${escapeHtml(current.name)} · ${bytes(current.size)}`:'Other assets remain available under All'}</small></div><div class="slot"><b>Previous build</b><strong>None in preview</strong><small>After an update, the prior build would be shown here.</small></div></div></article>`}).join(''):emptyState('No releases','Select repositories with published builds to see them here.','add-source','Add a source')}`}
function renderProjectSettings(p){return `<div class="settings-grid"><section class="panel"><h3>Project settings</h3><p class="muted" style="font-size:12px;line-height:1.5;margin-top:-6px">Changes here affect only this project. Repository list layout is a separate view preference.</p><div class="form-stack"><div class="field"><label for="settings-name">Project name</label><input id="settings-name" value="${escapeHtml(p.name)}"></div><div class="field"><label for="settings-folder">Project folder</label><input id="settings-folder" value="${escapeHtml(p.folder)}"><span class="field-help">The native app will validate this location before any file operation.</span></div><div class="form-row"><div class="field"><label for="settings-provider">Git provider</label><select id="settings-provider">${providers.map(v=>`<option value="${v.id}" ${p.provider===v.id?'selected':''}>${escapeHtml(v.name)}</option>`).join('')}</select></div><div class="field"><label for="settings-account">Connected account</label><input id="settings-account" value="${escapeHtml(p.account||'')}"></div></div><div class="field"><label for="settings-disk">Folder layout on disk</label><select id="settings-disk"><option value="grouped" ${p.disk==='grouped'?'selected':''}>Grouped · owner / repository</option><option value="flat" ${p.disk==='flat'?'selected':''}>Flat · repository</option></select></div><div class="notice">${svg('shield',16)} Connection in this website is a design preview. No token is requested or stored.</div><div><button class="btn primary" data-action="save-project-settings">Save project settings</button></div></div></section><div><section class="panel" style="margin-bottom:16px"><h3>Project boundary</h3><div class="info-list"><div class="info-row"><span>Folder</span><strong>${escapeHtml(p.folder)}</strong></div><div class="info-row"><span>Provider</span><strong>${escapeHtml(provider(p.provider).name)}</strong></div><div class="info-row"><span>Sources</span><strong>${p.sources.length}</strong></div></div></section><section class="danger-panel"><h3>Delete project</h3><p>Remove this project from the dashboard. The native app should leave the folder and cloned files on disk unless you separately choose to remove them.</p><button class="btn danger small" data-action="confirm-delete">Delete project</button></section></div></div>`}
function renderStore(){const all=state.projects.flatMap(p=>projectRepos(p).map(r=>({...r,projectName:p.name}))).filter((r,i,a)=>a.findIndex(x=>x.id===r.id)===i);const featured=all.find(r=>r.id==='prism')||all[0];return `<div class="page-head"><div><div class="eyebrow">LOCAL APP STORE</div><h1>Apps from every project.</h1><p>One place for installable releases across your selected repositories. Open app details, compare assets, and preview install states.</p></div></div>${featured?`<div class="store-feature"><div><div class="eyebrow">FEATURED IN YOUR WORKSPACE</div><h2>${escapeHtml(featured.name)}</h2><p>${escapeHtml(featured.description)}</p><button class="btn small" data-action="app-detail" data-id="${escapeHtml(featured.id)}">Explore app details ${svg('arrow',13)}</button></div><img src="assets/${escapeHtml(featured.icon)}" alt=""></div>`:''}<div class="toolbar"><div class="toolbar-left"><h2 style="font:800 16px var(--display);margin:0">All applications <span class="muted">${all.length}</span></h2></div><span class="segmented">${['All','macOS','Windows','Linux'].map(pl=>`<button data-action="store-platform" data-platform="${pl}" class="${state.storePlatform===pl?'active':''}">${pl}</button>`).join('')}</span></div>${all.length?`<div class="store-grid">${all.filter(r=>state.storePlatform==='All'||r.releases.some(rel=>rel.assets.some(a=>a.platform===state.storePlatform))).map(r=>`<article class="card store-card clickable-card" role="button" tabindex="0" data-action="app-detail" data-id="${escapeHtml(r.id)}" aria-label="Open ${escapeHtml(r.name)} details"><div class="store-card-top">${icon(r)}<div><h3>${escapeHtml(r.name)}</h3><span class="muted" style="font-size:10px">${escapeHtml(r.type)}</span></div></div><p>${escapeHtml(r.description)}</p><div><span class="chip blue">${escapeHtml(r.releases[0]?.tag||'No release')}</span> <span class="chip">${escapeHtml(r.projectName)}</span></div><footer><small>${installAction(r)==='Update'?`Update available · ${escapeHtml(state.installs[r.id])}`:installAction(r)==='Open'?'Up to date · preview':'Available · preview'}</small><button class="btn small ${installAction(r)==='Open'?'':'primary'}" data-action="store-action" data-id="${escapeHtml(r.id)}">${installAction(r)}</button></footer></article>`).join('')}</div>`:emptyState('No apps yet','Create a project and select repositories with releases.','new-project','Create a project')}<div class="notice warn" style="margin-top:18px">Design prototype: Install, Update, and Open only change the preview state. No files are downloaded or launched.</div>`}
function emptyState(title,body,action,label){return `<div class="empty-state"><span class="empty-icon">${svg('folder',25)}</span><h3>${escapeHtml(title)}</h3><p>${escapeHtml(body)}</p><button class="btn primary small" data-action="${action}">${escapeHtml(label)}</button></div>`}
function renderModal(){if(state.modal==='wizard')return renderWizard();if(state.modal==='source')return renderSourceModal();if(state.modal==='delete')return `<div class="modal-backdrop" data-action="close-modal-backdrop"><div class="modal small" role="dialog" aria-modal="true" aria-labelledby="delete-title"><div class="modal-head"><div><div class="eyebrow">PROJECT SETTINGS</div><h2 id="delete-title">Delete ${escapeHtml(project()?.name)}?</h2><p>This removes the project from this preview. Your actual folders are not touched.</p></div><button class="btn ghost icon-btn" data-action="close-modal" aria-label="Close">${svg('close')}</button></div><div class="notice warn">This action is available only from the selected project’s Settings view.</div><div class="wizard-foot"><button class="btn" data-action="close-modal">Cancel</button><button class="btn danger" data-action="delete-project">Delete project</button></div></div></div>`;if(state.modal?.startsWith('app:')||state.modal?.startsWith('release:')){const id=state.modal.split(':')[1],r=repo(id),rel=r.releases[0];return `<div class="modal-backdrop" data-action="close-modal-backdrop"><div class="modal" role="dialog" aria-modal="true"><div class="modal-head"><div class="repo-detail-head" style="margin:0">${icon(r)}<div><div class="eyebrow">${state.modal.startsWith('app:')?'APP DETAILS':'RELEASE DETAILS'}</div><h2 style="margin:2px 0">${escapeHtml(r.name)}</h2><p>${escapeHtml(r.owner)} · ${escapeHtml(rel?.tag||'No release')}</p></div></div><button class="btn ghost icon-btn" data-action="close-modal" aria-label="Close">${svg('close')}</button></div><p class="muted" style="font-size:12px;line-height:1.6">${escapeHtml(r.description)}</p><div class="section-head"><h2>Release notes</h2><span class="muted" style="font-size:11px">${escapeHtml(rel?.date||'')}</span></div><p style="font-size:13px">${escapeHtml(rel?.notes||'No notes in this preview.')}</p><div class="section-head"><h2>Available builds</h2></div><div class="repo-pick">${(rel?.assets||[]).map(a=>`<div class="pick-row">${svg('download',15)}<span><strong>${escapeHtml(a.name)}</strong><small>${escapeHtml(a.platform)} · ${escapeHtml(a.type)} · ${bytes(a.size)}</small></span><span class="chip blue">${escapeHtml(a.platform)}</span></div>`).join('')}</div><div class="wizard-foot"><span class="muted" style="font-size:10px">All assets are fictional UI examples.</span><button class="btn" data-action="close-modal">Done</button></div></div></div>`}return ''}
function renderWizard(){const w=state.wizard,step=w.step;return `<div class="modal-backdrop" data-action="close-modal-backdrop"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="wizard-title"><div class="modal-head"><div><div class="eyebrow">NEW PROJECT · STEP ${step+1} OF 3</div><h2 id="wizard-title">${['Name and folder','Choose a Git provider','Workspace preferences'][step]}</h2><p>${['A project points to one directory on your computer.','Each project can use a different provider and account.','Disk layout controls clone paths. You can change the on-screen list layout separately.'][step]}</p></div><button class="btn ghost icon-btn" data-action="close-modal" aria-label="Close">${svg('close')}</button></div><div class="stepper">${[0,1,2].map(i=>`<span class="step ${i<=step?'done':''}"></span>`).join('')}</div>${step===0?`<div class="form-stack"><div class="field"><label for="wizard-name">Project name</label><input id="wizard-name" value="${escapeHtml(w.name)}" placeholder="e.g. My Product Suite" autofocus></div><div class="field"><label for="wizard-folder">Directory on disk</label><input id="wizard-folder" value="${escapeHtml(w.folder)}" placeholder="e.g. ~/Projects/My Product Suite"><span class="field-help">In the native app this will use a folder picker and validate the actual path.</span></div><div class="notice">${svg('folder',16)} Your project owns this folder. Different projects may point to different drives or directories.</div></div>`:step===1?`<div class="provider-grid">${providers.map(p=>`<button class="provider-option ${w.provider===p.id?'selected':''}" data-action="select-provider" data-provider="${p.id}"><span class="provider-logo ${p.id}">${providerIcon(p)}</span><span><strong>${escapeHtml(p.name)}</strong><small>${escapeHtml(p.sub)}</small></span></button>`).join('')}</div><div class="form-row" style="margin-top:18px"><div class="field"><label for="wizard-account">Account or organization</label><input id="wizard-account" value="${escapeHtml(w.account)}" placeholder="e.g. my-team"></div>${w.provider==='custom'?`<div class="field"><label for="wizard-host">Git server URL</label><input id="wizard-host" value="${escapeHtml(w.host)}" placeholder="https://git.example.com"></div>`:''}</div><div class="notice" style="margin-top:15px">${svg('shield',16)} Connection is simulated here. The native app will request a token or OAuth login and store credentials in the OS secure store per project.</div>`:`<div class="choice-grid"><button class="choice ${w.disk==='grouped'?'selected':''}" data-action="select-disk" data-disk="grouped">${svg('layers',20)}<strong>Grouped on disk</strong><span>Project folder / account / repository. Best when the project includes several people or organizations.</span></button><button class="choice ${w.disk==='flat'?'selected':''}" data-action="select-disk" data-disk="flat">${svg('list',20)}<strong>Flat on disk</strong><span>Project folder / repository. Works when repository names are unique within the project.</span></button></div><div class="panel" style="margin-top:17px;background:#f8f9ff"><h3>Review your project</h3><div class="info-list"><div class="info-row"><span>Name</span><strong>${escapeHtml(w.name||'Untitled')}</strong></div><div class="info-row"><span>Folder</span><strong>${escapeHtml(w.folder||'Not selected')}</strong></div><div class="info-row"><span>Provider</span><strong>${escapeHtml(provider(w.provider).name)}</strong></div><div class="info-row"><span>Account</span><strong>${escapeHtml(w.account||'Not selected')}</strong></div><div class="info-row"><span>Disk layout</span><strong>${w.disk==='grouped'?'Grouped':'Flat'}</strong></div></div></div>`}<div class="wizard-foot"><button class="btn" data-action="wizard-back">${step===0?'Cancel':'Back'}</button><button class="btn primary" data-action="wizard-next">${step===2?'Create project':'Continue'} ${svg('arrow',14)}</button></div></div></div>`}
function renderSourceModal(){const p=project(),handle=state.sourceDraft||'',choices=['prism','quill','atlas','orbit','relay'];return `<div class="modal-backdrop" data-action="close-modal-backdrop"><div class="modal small" role="dialog" aria-modal="true"><div class="modal-head"><div><div class="eyebrow">ADD SOURCE</div><h2>Find a person or organization</h2><p>Enter a ${escapeHtml(provider(p.provider).name)} handle or profile URL to preview repository selection.</p></div><button class="btn ghost icon-btn" data-action="close-modal" aria-label="Close">${svg('close')}</button></div><div class="field"><label for="source-input">Handle or profile link</label><input id="source-input" value="${escapeHtml(handle)}" placeholder="e.g. design-team or https://…"></div><div class="notice" style="margin:15px 0">Sample results below illustrate the selection flow. No network request occurs.</div><div class="repo-pick">${choices.map(id=>{const r=repo(id);return `<label class="pick-row"><input type="checkbox" name="source-repo" value="${id}" ${p.repos.includes(id)?'checked':''}><span><strong>${escapeHtml(r.name)}</strong><small>${escapeHtml(r.description)}</small></span>${r.private?'<span class="chip">Private</span>':''}</label>`}).join('')}</div><div class="wizard-foot"><button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="save-source">Add selected repositories</button></div></div></div>`}
function navigate(view){state.view=view;state.modal=null;state.search='';window.scrollTo(0,0);render()}
function syncWizard(){const w=state.wizard;const el=id=>document.getElementById(id);if(el('wizard-name'))w.name=el('wizard-name').value.trim();if(el('wizard-folder'))w.folder=el('wizard-folder').value.trim();if(el('wizard-account'))w.account=el('wizard-account').value.trim();if(el('wizard-host'))w.host=el('wizard-host').value.trim()}
document.addEventListener('click',handleClick);
function handleClick(e){const node=e.target.closest('[data-action]');if(!node)return;const action=node.dataset.action;const id=node.dataset.id;if(action==='close-modal-backdrop'&&e.target!==node)return;if(action==='hub'){navigate('hub');return}if(action==='store'){navigate('store');return}if(action==='open-project'){state.projectId=id;state.tab='overview';state.repoId=project()?.repos[0]||'';navigate('project');return}if(action==='project-tab'){state.tab=node.dataset.tab;state.search='';render();return}if(action==='new-project'){state.wizard={step:0,name:'',folder:'',provider:'github',host:'',account:'',disk:'grouped'};state.modal='wizard';render();return}if(action==='close-modal'||action==='close-modal-backdrop'){state.modal=null;render();return}if(action==='wizard-back'){syncWizard();if(state.wizard.step===0)state.modal=null;else state.wizard.step--;render();return}if(action==='wizard-next'){syncWizard();const w=state.wizard;if(w.step===0&&(!w.name||!w.folder)){toast('Add a project name and folder to continue.');return}if(w.step===1&&(!w.account||(w.provider==='custom'&&!/^https:\/\/[\w.-]+(?::\d+)?\/?$/.test(w.host)))){toast('Choose an account and a valid HTTPS server URL for Custom Git.');return}if(w.step<2){w.step++;render();return}const p={id:'project-'+Date.now(),name:w.name,folder:w.folder,provider:w.provider,account:w.account,disk:w.disk,sources:[],repos:[],demo:false};state.projects.push(p);persist();state.modal=null;state.projectId=p.id;state.tab='overview';state.view='project';toast('Project created in this design preview.');return}if(action==='select-provider'){syncWizard();state.wizard.provider=node.dataset.provider;render();return}if(action==='select-disk'){state.wizard.disk=node.dataset.disk;render();return}if(action==='list-mode'){state.listMode=node.dataset.mode;render();return}if(action==='select-repo'){state.repoId=id;render();return}if(action==='platform'){state.platform=node.dataset.platform;render();return}if(action==='store-platform'){state.storePlatform=node.dataset.platform;render();return}if(action==='add-source'){state.sourceDraft='';state.modal='source';render();return}if(action==='save-source'){const p=project(),raw=document.getElementById('source-input')?.value.trim()||'';if(!raw){toast('Enter a handle or profile URL.');return}const handle=raw.replace(/\/$/,'').split('/').pop().replace(/^@/,'');if(!handle){toast('Enter a valid handle.');return}const selected=[...document.querySelectorAll('input[name="source-repo"]:checked')].map(x=>x.value);if(!p.sources.includes(handle))p.sources.push(handle);p.repos=[...new Set([...p.repos,...selected])];persist();state.modal=null;state.tab='repositories';state.repoId=selected[0]||p.repos[0]||'';toast(`Added ${selected.length} sample repositories for ${handle}.`);return}if(action==='save-project-settings'){const p=project();if(!p||state.tab!=='settings')return;const name=document.getElementById('settings-name').value.trim(),folder=document.getElementById('settings-folder').value.trim(),account=document.getElementById('settings-account').value.trim();if(!name||!folder){toast('Name and folder are required.');return}Object.assign(p,{name,folder,account,provider:document.getElementById('settings-provider').value,disk:document.getElementById('settings-disk').value});persist();toast('Project settings updated in this preview.');return}if(action==='confirm-delete'){if(state.view!=='project'||state.tab!=='settings')return;state.modal='delete';render();return}if(action==='delete-project'){if(state.tab!=='settings')return;state.projects=state.projects.filter(p=>p.id!==state.projectId);persist();state.projectId=null;state.modal=null;state.view='hub';toast('Project removed from this preview.');return}if(action==='app-detail'){state.modal='app:'+id;render();return}if(action==='show-release'){state.modal='release:'+id;render();return}if(action==='store-action'){const r=repo(id),next=installAction(r);if(next==='Open'){toast(`Opening ${r.name} is simulated in this preview.`)}else{state.installs[id]=r.releases[0]?.tag||'sample';persist();toast(`${r.name} marked ${next==='Update'?'updated':'installed'} in this preview.`)}return}if(action==='dismiss-toast'){state.toast='';render();return}}
document.addEventListener('input',e=>{if(e.target.id==='repo-search'){state.search=e.target.value;const focused=e.target;render();const next=document.getElementById('repo-search');if(next){next.focus();next.setSelectionRange(focused.selectionStart,focused.selectionEnd)}}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.modal){state.modal=null;render();return}if((e.key==='Enter'||e.key===' ')&&e.target.matches('.clickable-card')){e.preventDefault();handleClick({target:e.target})}});
render();
